{
  "outcome": "escalate",
  "rationale": "We must escalate this claim because it remains unclear whether an exclusion applies due to the claimant's admission of potential speeding and racing. Clause STD-6.2 governs this referral since material facts regarding an impromptu speed contest are open to interpretation.",
  "citations": [
    {
      "clause_id": "STD-6.2",
      "quote": "If the documents submitted do not allow the adjuster to determine whether an exclusion applies, because material facts are disputed, missing or open to more than one reasonable reading, the claim must be escalated for further investigation rather than approved or denied on the information available."
    }
  ]
}
